// Offline AArch64 relocation example: the instruction bytes and the virtual
// address they came from are unrelated.
//
// The firmware image is not mapped at the host address where its bytes are
// readable. GenRelocateCode takes the readable copy as `buffer` and uses
// origin->addr() only to compute PC-relative targets (literal loads, ADR/ADRP,
// direct branches). Nothing here installs a hook: the offline memory adapter
// only stores the generated bytes.
//
// Build (offline, data-only):
//   c++ -std=c++17 -O2 -DDOBBY_LOGGING_DISABLE \
//     -Isource -Isource/dobby -Iinclude -I. -Iexternal -Iexternal/logging \
//     source/InstructionRelocation/arm64/InstructionRelocationARM64.cc \
//     support/memory_adapter.cc examples/offline_relocation_example.cc \
//     -o offline_relocation_example
//   ./offline_relocation_example

#include "InstructionRelocation/InstructionRelocation.h"

#include <cstdint>
#include <cstdio>

int main() {
  // Two instructions copied out of a firmware image: `nop` followed by
  // `ldr x0, #8`, a literal load whose data lives 8 bytes after the
  // instruction's virtual address.
  uint32_t image_copy[2] = {0xD503201Fu, 0x58000040u}; // ldr x0, #+8
  const uint64_t image_va = 0xFFFF800000201000ull;     // nowhere near image_copy

  CodeMemBlock origin(addr_t(image_va), sizeof(image_copy));
  CodeMemBlock relocated;
  GenRelocateCode(image_copy, &origin, &relocated, false);

  if (relocated.addr() == 0 || origin.size != sizeof(image_copy)) {
    std::fprintf(stderr, "relocation failed\n");
    return 1;
  }

  // The rewrite materializes the *original* data address with x17 and performs
  // the original access class, so the data stays in the image:
  //   movz/movk x17, #0xFFFF800000201008 ; ldr x0, [x17]
  const uint32_t *words = reinterpret_cast<const uint32_t *>(relocated.addr());
  std::printf("relocated %zu bytes, first word %08x, move-wide word %08x\n", (size_t)relocated.size, words[0],
              words[1]);

  // `origin.size` is the number of whole instruction bytes consumed.
  std::printf("consumed %zu bytes of origin\n", (size_t)origin.size);

  // Proof that the fetch source and the PC source are independent: the same
  // bytes can be relocated again under a different virtual address.
  CodeMemBlock other_origin(addr_t(0x0000000000400000ull), sizeof(image_copy));
  CodeMemBlock other_relocated;
  GenRelocateCode(image_copy, &other_origin, &other_relocated, false);
  const uint32_t *other_words = reinterpret_cast<const uint32_t *>(other_relocated.addr());
  std::printf("same bytes, other va -> move-wide word %08x (varies with the address)\n", other_words[1]);

  return 0;
}
